import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import "../../style/blog.css";

const BlogPage = () => {
  const [blogs, setBlogs] = useState([]);

  useEffect(() => {
    // Sample blog data (later you can fetch from backend using ApiService)
    const sampleBlogs = [
      {
        id: 1,
        title: "Top 10 Gadgets You Need in 2025",
        date: "August 15, 2025",
        image: "/images/blog1.jpg",
        excerpt:
          "From smart home devices to AI-powered assistants, here’s our pick of must-have tech in 2025."
      },
      {
        id: 2,
        title: "How to Choose the Right Laptop",
        date: "August 10, 2025",
        image: "/images/blog2.jpg",
        excerpt:
          "We break down the specs, brands, and features to help you buy the perfect laptop for your needs."
      },
      {
        id: 3,
        title: "The Future of Wearable Technology",
        date: "August 5, 2025",
        image: "/images/blog3.jpg",
        excerpt:
          "From fitness trackers to AR glasses, wearables are evolving fast. Here’s what’s coming next."
      }
    ];

    setBlogs(sampleBlogs);
  }, []);

  return (
    <div className="blog-page">
      <h1>Our Blog</h1>
      <div className="blog-grid">
        {blogs.map((blog) => (
          <div key={blog.id} className="blog-card">
            <Link to={`/blog/${blog.id}`}>
              <img src={blog.image} alt={blog.title} />
              <h2>{blog.title}</h2>
            </Link>
            <p className="date">{blog.date}</p>
            <p className="excerpt">{blog.excerpt}</p>
            <Link to={`/blog/${blog.id}`} className="read-more">
              Read More →
            </Link>
          </div>
        ))}
      </div>
    </div>
  );
};

export default BlogPage;
